// Group open action items by Assigned To (email). Mirrors "Group by Lead" in the CCF reminder workflow.
const r = $input.first().json;               // Forms · List Tasks output: { ok, tasks[], count, ... }
const cfg = $('Workflow Configuration').first().json;
const tasks = Array.isArray(r.tasks) ? r.tasks : [];
const groups = {};
const ageDays = (iso) => { const t = new Date(iso).getTime(); return isNaN(t) ? null : Math.floor((Date.now() - t) / 86400000); };
for (const t of tasks) {
  const assignee = String(t.assignedTo || '').trim().toLowerCase();
  if (!assignee || !assignee.includes('@')) continue;
  if (!groups[assignee]) groups[assignee] = { assignee, tasks: [] };
  groups[assignee].tasks.push({
    taskId: t.taskId, workflowId: t.workflowId, category: t.category, name: t.name, formType: t.formType,
    items: Array.isArray(t.description) ? t.description.filter(d => typeof d === 'string' && !d.startsWith('__')) : [],
    createdDate: t.createdDate, ageDays: ageDays(t.createdDate), hasDraft: !!t.draft
  });
}
const out = Object.values(groups).map(g => { g.tasks.sort((a, b) => (b.ageDays || 0) - (a.ageDays || 0)); g.count = g.tasks.length; g.oldestDays = g.tasks[0] ? g.tasks[0].ageDays : 0; return g; });
if (cfg.minTasks && Number(cfg.minTasks) > 1) return out.filter(g => g.count >= Number(cfg.minTasks)).map(g => ({ json: g }));
return out.map(g => ({ json: g }));

// Build one HTML email per assignee — same visual style as the CCF Tracker reminder (header bar, item cards, footer).
const g = $input.item.json;
const cfg = $('Workflow Configuration').first().json;
const count = g.count;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
const portal = cfg.portalUrl && !String(cfg.portalUrl).startsWith('<<') ? String(cfg.portalUrl) : '';
const subject = 'Employee Forms Reminder: ' + count + ' open action item' + (count !== 1 ? 's' : '') + ' assigned to you';
let html = '<html><head><style>' +
  'body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }' +
  '.header { background-color: #f4f4f4; padding: 15px; border-left: 4px solid #0066cc; }' +
  '.content { padding: 20px; }' +
  '.task-item { margin-bottom: 15px; padding: 10px; background-color: #f9f9f9; border-radius: 5px; }' +
  '.age { color: #d9534f; font-weight: bold; }' +
  '.footer { margin-top: 30px; padding-top: 15px; border-top: 1px solid #ddd; font-size: 0.9em; color: #666; }' +
  '</style></head><body>' +
  '<div class="header"><h2>Employee Forms – Open Action Items Reminder</h2></div><div class="content">' +
  '<p>Hello,</p><p>You have <strong>' + count + '</strong> open action item' + (count !== 1 ? 's' : '') + ' in the Employee Forms portal' + (g.oldestDays ? ' (oldest: <span class="age">' + g.oldestDays + ' days</span>)' : '') + '.</p>' +
  '<p>Please review and complete the following:</p><ul>';
for (const t of g.tasks) {
  const link = portal ? '<a href="' + portal + '?page=requestdetails&id=' + encodeURIComponent(t.workflowId) + '" target="_blank">' + esc(t.workflowId) + '</a>' : esc(t.workflowId);
  html += '<li class="task-item"><strong>' + esc(t.category || t.formType) + ':</strong> ' + esc(t.name) + '<br>' +
    '<strong>Workflow:</strong> ' + link + ' &nbsp;·&nbsp; <strong>Task:</strong> ' + esc(t.taskId) + '<br>' +
    '<strong>Open for:</strong> <span class="age">' + (t.ageDays == null ? '?' : t.ageDays) + ' day' + (t.ageDays === 1 ? '' : 's') + '</span>' + (t.hasDraft ? ' &nbsp;·&nbsp; draft saved' : '') +
    (t.items.length ? '<br><small>' + t.items.map(esc).join(' · ') + '</small>' : '') + '</li>';
}
html += '</ul>' +
  (portal ? '<p><strong>LINK TO PORTAL:</strong><br><a href="' + portal + '?page=dashboard" target="_blank">Employee Forms – My Tasks</a></p>' : '') +
  '<div class="footer"><p>This is an automated reminder from the Employee Forms portal (via n8n). Reply to IT if a task is no longer yours.</p></div>' +
  '</div></body></html>';
const override = cfg.recipientOverride && !String(cfg.recipientOverride).startsWith('<<') ? String(cfg.recipientOverride) : '';
return { assignee: g.assignee, sendTo: override || g.assignee, overridden: !!override, subject: (override ? '[TEST → ' + g.assignee + '] ' : '') + subject, html, count };
